"""What every generator of ``linecaster docs`` shares: the header of a generated file, Markdown tables, and links
(within ``docs/`` relative, to the rest of the repository on GitHub)."""
from __future__ import annotations

import os
from dataclasses import dataclass
from pathlib import Path

#: where links to the repository's files outside ``docs/`` point (source files, the root README, pipelines/)
GITHUB = "https://github.com/storytracer/linecaster/blob/main"
#: the docs site's current release, where links to generated pages from outside the site point (llms.txt)
SITE = "https://storytracer.github.io/linecaster/latest"
#: the first line of every generated Markdown page
HEADER = "<!-- Generated by `linecaster docs`: edit the code, the docstrings or the catalog, not this file. -->"


def table(header: tuple, rows: list[tuple]) -> list[str]:
    """A Markdown table, ``|`` and newlines in cells escaped, and a blank line after it."""
    cell = lambda v: str(v).replace("|", "\\|").replace("\n", " ")  # noqa: E731
    return [f"| {' | '.join(header)} |", f"|{'---|' * len(header)}",
            *[f"| {' | '.join(cell(v) for v in r)} |" for r in rows], ""]


@dataclass(frozen=True)
class Links:
    """Links from a generated page: relative within ``docs_root``, on GitHub for the rest of ``repo``, relative for
    anything else (a catalog outside the checkout)."""

    docs_root: Path
    repo: Path | None = None

    def to(self, target: str | Path, frm: str | Path) -> str:
        """The link to ``target`` from a page in the folder ``frm``."""
        t, here = Path(target).resolve(), Path(frm).resolve()
        if t.is_relative_to(self.docs_root.resolve()):
            return os.path.relpath(t, here)
        if self.repo is not None and t.is_relative_to(self.repo.resolve()):
            return f"{GITHUB}/{t.relative_to(self.repo.resolve()).as_posix()}"
        return os.path.relpath(t, here)
